import{_ as a,H as p,f as t,i}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"特别策划 | AI时代程序员生存之道","description":"","frontmatter":{},"headers":[{"level":2,"title":"大模型时代程序员要掌握哪些能力（直播回放）","slug":"大模型时代程序员要掌握哪些能力-直播回放","link":"#大模型时代程序员要掌握哪些能力-直播回放","children":[]},{"level":2,"title":"铜弹 AI：加快知识的“周转率”","slug":"铜弹-ai-加快知识的-周转率","link":"#铜弹-ai-加快知识的-周转率","children":[]},{"level":2,"title":"处理本质困难的进展","slug":"处理本质困难的进展","link":"#处理本质困难的进展","children":[{"level":3,"title":"敏捷软件开发","slug":"敏捷软件开发","link":"#敏捷软件开发","children":[]},{"level":3,"title":"领域驱动设计","slug":"领域驱动设计","link":"#领域驱动设计","children":[]}]},{"level":2,"title":"AI 时代的程序员应发展哪些能力？","slug":"ai-时代的程序员应发展哪些能力","link":"#ai-时代的程序员应发展哪些能力","children":[]}],"relativePath":"手把手教你落地DDD/特别策划｜AI时代程序员生存之道.md","filePath":"手把手教你落地DDD/特别策划｜AI时代程序员生存之道.md","lastUpdated":1795557830000}'),A={name:"手把手教你落地DDD/特别策划｜AI时代程序员生存之道.md"};function l(r,e,E,n,s,o){return p(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="特别策划-ai时代程序员生存之道" tabindex="-1">特别策划 | AI时代程序员生存之道 <a class="header-anchor" href="#特别策划-ai时代程序员生存之道" aria-label="Permalink to &quot;特别策划 | AI时代程序员生存之道&quot;">​</a></h1><p>你好，我是钟敬。</p><p>上一次加餐，我们讨论了 AI 的能力边界。如果我们认可“没有银弹”的理论，那么显然现在的AI 也不是银弹。</p><p>不过，目前 AI 在软件开发中已经可以帮我们做不少事情了，当得起一颗“铜弹”了。我们可以想象一下，如果一个程序员善用 AI，提高了 30% 的效率，而别的程序员只提高了 10%，甚至没有提高。那么这个程序员的竞争力必然提升。推而广之，对于一个企业也是如此。</p><p>今天我们先聊聊 AI 可以帮助我们做哪些事，然后在这个基础上，讨论在 AI 时代，开发人员应该更加注重发展哪些能力。</p><h2 id="大模型时代程序员要掌握哪些能力-直播回放" tabindex="-1">大模型时代程序员要掌握哪些能力（直播回放） <a class="header-anchor" href="#大模型时代程序员要掌握哪些能力-直播回放" aria-label="Permalink to &quot;大模型时代程序员要掌握哪些能力（直播回放）&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/%25E7%2589%25B9%25E5%2588%25AB%25E7%25AD%2596%25E5%2588%2592-AI%25E6%2597%25B6%25E4%25BB%25A3%25E7%25A8%258B%25E5%25BA%258F%25E5%2591%2598%25E7%2594%259F%25E5%25AD%2598%25E4%25B9%258B%25E9%2581%2593/1.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/%25E7%2589%25B9%25E5%2588%25AB%25E7%25AD%2596%25E5%2588%2592-AI%25E6%2597%25B6%25E4%25BB%25A3%25E7%25A8%258B%25E5%25BA%258F%25E5%2591%2598%25E7%2594%259F%25E5%25AD%2598%25E4%25B9%258B%25E9%2581%2593/1.jpeg" alt=""></a></p><h2 id="铜弹-ai-加快知识的-周转率" tabindex="-1">铜弹 AI：加快知识的“周转率” <a class="header-anchor" href="#铜弹-ai-加快知识的-周转率" aria-label="Permalink to &quot;铜弹 AI：加快知识的“周转率”&quot;">​</a></h2><p>具体来说，AI 可以帮我们做这几方面的事情。</p><p>第一，AI 能够帮助开发人员完成重复性和套路性的工作。</p><p>避免重复是软件开发中一个常见的原则。但就目前的技术而言，仍然有很多重复性的工作很难避免，例如所谓“样板代码”。而 AI 可以通过模仿程序员写代码的方式，自动生成部分具有重复性的代码，从而节省了编写代码的时间。</p><p>第二，AI 可以帮助开发人员完成那些了解原理但忘记技术细节的代码。</p><p>比如说，我已经多年没有写 JavaScript 了。虽然，原理还记得，但一些具体的语法和 API 忘记了。如果在过去，需要查书或者利用搜索引擎查找资料才能回忆起来。而 AI 可以更快地告诉我这些技术细节，甚至自动生成代码，节省我们的开发时间。</p><p>第三，帮助开发人员提高学习新知识的速度。</p><p>比如我们有某个 JavaScript 框架没有掌握，如果擅于利用 AI，那么可以比传统的方法更快地学会它。</p><p>第四，可以帮助开发人员获取他人的经验。</p><p>AI 可以根据我们给的指令自动编写代码。AI 已经学习了很多别人写的代码，因此它生成的代码中可能包含其他人的经验，甚至可能会带来我们自己没有想到的新做法或新思路。</p><p>总的来说，软件开发可以看做一个知识的加工和创造的过程。而 AI 在软件开发中的作用，就是加快了知识加工的周转率。这一点决定了 AI 确实能在软件开发中发挥不小的作用。而另一方面，结合我们上节课讨论的软件开发的本质困难，决定了 AI 的作用是逐渐发挥的，而不会是飞跃性的。</p><h2 id="处理本质困难的进展" tabindex="-1">处理本质困难的进展 <a class="header-anchor" href="#处理本质困难的进展" aria-label="Permalink to &quot;处理本质困难的进展&quot;">​</a></h2><p>我们回头再看一看本质困难。尽管软件开发的本质困难是不能被消除的，但是人们已经发展出一些技术来提高解决本质困难的效率，使这些困难能够被可控地管理。</p><p>这里举两个例子，一个是敏捷软件开发，另一个是领域驱动设计。</p><h3 id="敏捷软件开发" tabindex="-1">敏捷软件开发 <a class="header-anchor" href="#敏捷软件开发" aria-label="Permalink to &quot;敏捷软件开发&quot;">​</a></h3><p>敏捷软件开发针对的本质困难，主要是复杂性、可变性和社会性。通过迭代的方式，敏捷软件开发使软件能够演进式地、有机地“生长”出来，从而把软件复杂性和可变性带来的困难和风险化整为零，分散在整个软件生命周期中。</p><p>比如说，复杂的需求，没有必要在项目前期确认和固化全部细节（事实上也是不可能的），而是在每个迭代的过程中逐步了解，这就降低了需求理解的复杂度。</p><p>敏捷的另一个核心理念是强调软件开发中“人”的方面，有一系列方法和技术提高沟通效率，改善人员组织，并且强调培养技术卓越的开发人员。</p><p>这些方法，针对的都是本质困难里的“社会性”。AI 目前在这方面提供的帮助，主要是提高人们的学习效率，培养卓越的开发人员。在产品设计、行业研究等方面也能提供帮助。</p><h3 id="领域驱动设计" tabindex="-1">领域驱动设计 <a class="header-anchor" href="#领域驱动设计" aria-label="Permalink to &quot;领域驱动设计&quot;">​</a></h3><p>领域驱动设计（DDD）并不是一个孤立的技术，而是属于软件开发方法学的范畴，是对传统面向对象方法学的一种优化。它针对的主要是复杂性、一致性和不可见性。</p><p>面对复杂的业务，我们必须找到一种能准确、深刻反映业务概念的手段，并且能够可视化地表达出来，这种手段就是领域模型。</p><p>围绕领域模型进行开发，就是 DDD 中所说的“模型驱动设计”。围绕着领域模型图，业务专家和开发人员就可以把业务的理解抽象化、严格化和规范化，也可以用一致的语言来沟通，这就是 DDD 中说的“统一语言”。</p><p>在这一方面，AI 可以通过分析需求文本，初步建立领域模型，作为开发人员进一步优化的基础，在一定程度上节省了建模的时间。不过建模的主要工作，目前仍然需要人来进行。</p><h2 id="ai-时代的程序员应发展哪些能力" tabindex="-1">AI 时代的程序员应发展哪些能力？ <a class="header-anchor" href="#ai-时代的程序员应发展哪些能力" aria-label="Permalink to &quot;AI 时代的程序员应发展哪些能力？&quot;">​</a></h2><p>通过两篇加餐，我们现在应该已经对 AI 的能力边界有了一个总体的了解。</p><p>接下来，我们一起画张表格，总结一下 AI 能做什么以及不能做什么。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/%25E7%2589%25B9%25E5%2588%25AB%25E7%25AD%2596%25E5%2588%2592-AI%25E6%2597%25B6%25E4%25BB%25A3%25E7%25A8%258B%25E5%25BA%258F%25E5%2591%2598%25E7%2594%259F%25E5%25AD%2598%25E4%25B9%258B%25E9%2581%2593/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/%25E7%2589%25B9%25E5%2588%25AB%25E7%25AD%2596%25E5%2588%2592-AI%25E6%2597%25B6%25E4%25BB%25A3%25E7%25A8%258B%25E5%25BA%258F%25E5%2591%2598%25E7%2594%259F%25E5%25AD%2598%25E4%25B9%258B%25E9%2581%2593/2.png" alt=""></a></p><p>通过这些分析，我们可以得出结论，就是那些只会开发“垃圾代码”的程序员可能会面临危机了。这里的垃圾代码，指的是虽然功能大体上正确，但结构混乱，难以理解和维护的代码。过去，这样的程序员还有生存空间，毕竟写出的程序功能还是对的。但是，引入 AI 以后，很多基础性的代码可以自动生成了，这就压缩了这些程序员的生存空间。</p><p>那么，程序员应该加强哪些方面的能力呢？</p><p>首先，我们要加强理解业务需求的能力。</p><p>理解业务需求本身，AI 是无法代替的 。而如果开发人员理解了需求，并以领域模型等方式表达出来，那么剩下的一些事情就可以交给 AI 处理了。</p><p>如果我是一个开发编译器、云基础设施等底层机制的程序员，是不是就不需要理解业务的能力呢？其实不然。如果我开发的是云基础设施，那么使用云的开发、运维等人员，就是我的用户，他们的需求就是我的“业务需求”。所以，任何软件开发，都离不开对业务需求的理解。</p><p>其次就是熟练使用 AI 工具高效工作、快速学习的能力。</p><p>举个例子，基于大语言模型的 AI 有一个特点，就是只有问出好问题，才能得出好答案。我们所问的问题称为 Prompt（提示语），而如何给出好的提示语，已经形成了一个专门的技能——提示语工程。所以，如何才能更好地使用 AI，发挥 AI 的潜力，也是我们需要学习的技能。</p><p>除了工作提效，利用 AI 快速学习的能力也很重要。回想一下，搜索引擎的出现，实际上改变了我们的学习方式，加快了学习效率。类似地，AI 的出现，将会再次改变我们的学习方式。</p><p>接下来还有评审和验证 AI 生成代码的能力。</p><p>我们前面说过，AI 并不能保证生成的结果是最优化的，也就是说生成的可能也是“垃圾代码”。这就需要开发人员具备判断生成的代码质量的能力，以及进一步优化代码的能力。也就是掌握软件设计、整洁代码、重构等能力。</p><p>同样，AI 也不能保证生成的代码的正确性，因此开发人员必须能验证这些代码正确性。我们可以逐行分析 AI 生成的代码，但是这样仍然可能漏掉一些要点。比较好的方式是为生成的代码编写自动化测试，从需求的角度反向验证正确性。当然，测试代码也是可以用 AI 辅助生成的。</p><p>最后，掌握软件开发各项技术的基本原理（而不是技术细节）的能力也不能忽视。</p><p>比如说，如果我已经了解 Vue.js 的基本原理，只是忘记了具体的语法细节，那么就非常适合在 AI 的辅助下开发基于 Vue.js 的程序。但是如果我一点都不了解原理，甚至 JavaScript 也不会，那么即使有 AI 的帮助，也难以达成目的。</p><p>这也提示我们，将来学习一门新技术的时候，可以把重点放在对原理的理解，而不用刻意记忆技术细节。</p><p>这里我再补充几点。这里我们对 AI 的评价，还是基于目前所看到的基于大语言模型的 AI 能力。但是技术发展日新月异。未来 AI 是否会产生新的技术突破，真正成为银弹，这种可能性永远无法排除。不过，单靠大语言模型这一项技术恐怕还做不到。</p><p>其次，开发人员虽然要有紧迫感，但也不必过于紧张。因为任何一项新技术的推行，本身就需要一个周期。所以我们还有时间，只要我们意识的问题的存在，按部就班地学习，就不会轻易掉队。</p><p>基于对 AI 能力的合理预期，虽然短期内 AI 对开发效率不会有突破性的提升，但是渐进式的提升效果也不容忽视。有人说过，“人与人之间的差距往往很小，然而这很小的差距有时却是决定性的。”</p><p>最后，咱们引用毛泽东思想中的一句话来总结我们对于 AI 辅助软件开发的态度：“战略上藐视敌人，战术上重视敌人”。所谓“战略上藐视”，就是不要太紧张，我们要看到 AI 的影响是渐进的，大家完全有时间，有能力掌握相关技术。所谓“战术上重视”，指的是现在就要开始行动了，主动关注相关技术的发展，最好尽快进行尝试。</p><p>好，今天我们就聊到这里。期待你在留言区分享你的思考，如果这两期加餐对你有启发，别忘了分享给更多朋友，我们再会。</p>',54)])])}const B=a(A,[["render",l]]);export{h as __pageData,B as default};
